      "summary": "「2:3:5比率（麺2:スープ3:トッピング5）」は、全10地域から自由に選べる【シニア級】でトッピング等のコツ回収・試食会回転を最大化するためのゲージ調整戦術です。【ジュニア級（東日本限定）】では仕様上2:3:5は作れず、基礎絆上げ・ステ下地作りが本来の役割です。",
