  "knowledge_sources": [
    {
      "title": "【ウマ娘】セレクトガチャ＆SSR引換券『おすすめ最強サポカTier！』最新環境サポカ編成や今後の環境まとめ！【5.5周年攻略】",
      "author": "NottinTV",
      "type": "YouTube動画",
      "badge": "YouTube",
      "url": "https://youtu.be/PQuIDn_1AZ0",
      "key_takeaways": [
        "5周年実装の「SSR フォーエバーヤング［Innovator］」は完凸得意率100を誇り、ダート金スキル2種（コール＆レスポンス/イノベーション）または汎用金スキル2種（尻尾の滝登り/前人未到）を選択可能。ダート全脚質で必須枠、芝でもTier SS+に君臨。",
        "5.5周年セレクトステップアップ＆引換券における最新Tierランキングを完全網羅。",
        "「SSR トウカイテイオー（天才的ユートピア）」「SSR エアグルーヴ（心覚えし、京の華）」がスピード最上位Tierとして不動。",
        "賢さ枠では「SSR デアリングタクト［無垢の白妙］」と「SSR ウインバリアシオン［水面のプリンシパル］」の優先度が急上昇。",
        "SSR 駿川たづな（新仕様）は友人枠として無凸でも機能するが、完凸でお出かけ体力回復と育成安定度が最高潮に達する。"
      ]
    },
    {
      "title": "【完全版】これだけは持っておきたい!! 5.5周年サポカ＆ウマ娘完全まとめ 脚質別の優先度や方針・引換券ステップアップ解説",
      "author": "ぺが【pega channel】",
      "type": "YouTube動画",
      "badge": "YouTube",
      "url": "https://youtu.be/ooYkMSAq37c",
      "key_takeaways": [
        "脚質別のサポカ優先度：逃げ（ミホノブルボン/タップダンスシチー）、先行（エフフォーリア/ダイワスカーレット）、差し（ナイスネイチャ/エアグルーヴ）、追込（ミスターシービー/オルフェーヴル）の棲み分けを徹底解説。",
        "距離×脚質の組み合わせにおける必須加速スキルと、凸数が少なくても機能するサポカ（1凸運用可）の見極め基準を提示。",
        "引換券・結晶の使用優先度は『中途半端なカードを増やすより、現環境の核となる主力カードを3凸〜完凸させること』が最重要。"
      ]
    },
    {
      "title": "【ウマ娘】新シナリオ対応 完全版『最強SSR引換券・虹結晶おすすめランキング！』絶対に間違えたくない最強サポカ性能解説！",
      "author": "NottinTV",
      "type": "YouTube動画",
      "badge": "YouTube",
      "url": "https://youtu.be/fvNzw4f2wbA",
      "key_takeaways": [
        "周年引換券や虹の解放結晶を使うべきカードの厳選基準（腐りにくさ・練習性能・スキル汎用性）。",
        "「SSR オルフェーヴル（根性）」「SSR トウカイテイオー（スピード）」「SSR メイショウドトウ（スタミナ）」など、各ステータスを単体で引き上げる最高峰カードの凸数恩恵を実数値で比較。",
        "配布SSR（ハルウララ等）は完凸前提でガチャ産3凸並みに機能するため、無課金・微課金は配布完凸＋フレンド枠レンタル完凸の併用を強く推奨。"
      ]
    },
    {
      "title": "【ウマ娘】最強サポートカードランキング（トレセン軒シナリオTier表）",
      "author": "Game8（ゲームエイト）ウマ娘攻略班",
      "type": "Web攻略記事",
      "badge": "Game8公認",
      "url": "https://game8.jp/umamusume/372354",
      "key_takeaways": [
        "最新トレセン軒Tier表準拠：根性SS+格（アストンマーチャン）、SS格（ステイゴールド［気まぐれ渡り星］/デアリングタクト［白に至る純真］/ビコーペガサス）、スタミナSS+格（メイショウドトウ/キセキ）、SS格（フェノーメノ［ぬくもりのノエル］）、S格（カレンブーケドール［決意のフローラ］）。オルフェーヴルはTier A汎用枠として正確に位置付け。",
        "賢さ評価点10.0満点（フォーエバーヤング［Innovator］）の圧倒的汎用性と、各脚質特化賢さ（ダイワスカーレット/ウインバリアシオン/ミホノブルボン）の明確な序列。",
        "旧世代カード（初期キタサンブラック等）の現代環境における練習性能・スキルPt効率の型落ち評価を正確に反映。"
      ]
    }
  ],
